 "content": "def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    mr, mc = (r0 + r1) / 2, (c0 + c1) / 2
    marks = [(r, c, grid[r][c]) for r, row in enumerate(grid) for c, v in enumerate(row) if v not in (0, 5)]
    colors = {}
    for r, c, color in marks:
        quadrant = ('T' if r < mr else 'B') + ('L' if c < mc else 'R')
        colors[quadrant] = color
    # Each marker colors its quadrant and the diagonally opposite quadrant.
    qcolor = {}
    opposite = {'TL': 'BR', 'BR': 'TL', 'TR': 'BL', 'BL': 'TR'}
    for q, color in colors.items():
        qcolor[q] = color
        qcolor[opposite[q]] = color
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            q = ('T' if r < mr else 'B') + ('L' if c < mc else 'R')
            out[r][c] = qcolor[q]
    return out
